<span class="line">  <span class="token number">0.00</span> <span class="token number">100.00</span>   <span class="token number">0.57</span>  <span class="token number">99.85</span>  <span class="token number">94.32</span>  <span class="token number">81.09</span>    <span class="token number">550</span>   <span class="token number">14.204</span>    <span class="token number">34</span>    <span class="token number">4.002</span>   <span class="token number">845</span>    <span class="token number">0.990</span>   <span class="token number">19.196</span></span>
